#!/bin/bash
# the full suite against out/mainroot; $1 = log name
cd /home/user/mcu-tracker/mockup-data
export ROOT=$PWD/out/mainroot && L=${LOGDIR:-/tmp}/$1.log && : > $L && (fails=0; for s in check smoke feat; do echo "== $s" >> $L; node tests/$s.js >> $L 2>&1 || { echo "FAILED $s" >> $L; fails=$((fails+1)); }; done; for s in ct32 ct36 ct37b $(seq -f 'ct%g' 38 69); do echo "== $s" >> $L; node tests/$s.js $ROOT/index.html >> $L 2>&1 || { echo "FAILED $s" >> $L; fails=$((fails+1)); }; done; echo "== ct35 (test build)" >> $L; node tests/ct35.js >> $L 2>&1 || { echo "FAILED ct35" >> $L; fails=$((fails+1)); }; echo "== content" >> $L; node tests/content.js >> $L 2>&1 || { echo "FAILED content" >> $L; fails=$((fails+1)); }; echo "== swtest" >> $L; node tests/swtest.js $ROOT $ROOT/sw.js >> $L 2>&1 || { echo "FAILED swtest" >> $L; fails=$((fails+1)); }; echo "TOTAL FAILS $fails" >> $L) ; grep -c "^== " $L && grep -E "FAILED|TOTAL" $L
